function aggregate(){for(const [id,item] of Object.entries(report.cases)){const required=id.startsWith('P')?['chromium']:engines;const observations=item.observations.filter(x=>required.includes(x.engine));if(observations.some(x=>x.status==='FAIL')){item.status='FAIL';item.executionStatus='EXECUTED';}else if(observations.some(x=>x.status==='BLOCKED')){item.status='UNVERIFIED';item.executionStatus='BLOCKED';}else if(observations.length===required.length&&observations.every(x=>x.status==='PASS')){item.status='PASS';item.executionStatus='EXECUTED';}else{item.status='UNVERIFIED';item.executionStatus=observations.length?'PARTIAL':'NOT_RUN';}}}
function makeGuideRecord(){aggregate();const empty=()=>({status:'UNVERIFIED',notes:'',evidenceReference:'',screenshot:null,recordedAt:null});return {schema:1,candidate:payload.candidate,plan:payload.plan,reviewer:'Playwright automated browser execution; remaining human checks explicitly unverified',environment:report.engines.map(e=>e.engine+' '+e.browserVersion+' '+report.os).join('; '),sourceManifest:payload.sourceFingerprint,postLive:false,productionReference:'',cases:Object.fromEntries([...IDS,...LIVE].map(id=>{const row=report.cases[id];if(!row)return[id,empty()];return[id,{...empty(),status:row.status,notes:JSON.stringify({executionStatus:row.executionStatus,observations:row.observations}).slice(0,5000),evidenceReference:'results.json — '+id,recordedAt:row.status==='UNVERIFIED'?null:new Date().toISOString()}];})),permissions:{mascot:empty(),exceptions:empty()}};}
try{for(const engine of engines){await runEngine(engine);if(report.engines.at(-1)?.executionStatus==='BLOCKED')break;}}
finally{
  aggregate();const record=makeGuideRecord();report.completedAtUTC=new Date().toISOString();report.remainingCases=IDS.filter(id=>report.cases[id].status!=='PASS');report.progress={PASS:IDS.filter(id=>report.cases[id].status==='PASS').length,FAIL:IDS.filter(id=>report.cases[id].status==='FAIL').length,UNVERIFIED:IDS.filter(id=>report.cases[id].status==='UNVERIFIED').length};
  fs.writeFileSync(path.join(out,'results.json'),JSON.stringify(report,null,2)+'\n');fs.writeFileSync(path.join(out,'guide-record.json'),JSON.stringify(record,null,2)+'\n');
  const key=`altwing-manual-acceptance-v1:${payload.candidate}:${payload.plan}`;const safe=v=>JSON.stringify(v).replaceAll('<','\\u003c');
  const seed='<script>try{const k='+safe(key)+',n='+safe(record)+';const old=JSON.parse(localStorage.getItem(k)||"null");if(old&&old.candidate===n.candidate&&old.plan===n.plan){for(const id of Object.keys(n.cases)){if(old.cases?.[id]?.recordedAt&&old.cases[id].status!=="UNVERIFIED")n.cases[id]=old.cases[id];}}localStorage.setItem(k,JSON.stringify(n));}catch(e){console.error("Acceptance result restoration failed",e);}</script>';
  const guide=files.get('AltWing-Launch-Acceptance.html').toString().replace('<head>','<head>'+seed);fs.writeFileSync(path.join(out,'AltWing-Browser-Acceptance-Results.html'),guide);fs.writeFileSync(path.join(out,'AltWing-Launch-Preview.html'),files.get('AltWing-Launch-Preview.html'));
  const simple=['id,status,execution_status',...IDS.map(id=>[id,report.cases[id].status,report.cases[id].executionStatus].join(','))].join('\n');fs.writeFileSync(path.join(out,'case-statuses.csv'),simple+'\n');
  server.close();console.log('\nResults: '+out);console.log(JSON.stringify(report.progress));console.log('Open AltWing-Browser-Acceptance-Results.html for the existing populated guide. No production deployment or database write occurred.');
  process.exitCode=report.progress.FAIL?1:report.progress.UNVERIFIED?2:0;
}
